mapper.insert:
insert into ai_message (id, conversation_id, run_id, role, content, citations, status, seq, created_at)
values (#{id}, #{conversationId}, #{runId}, #{role}, #{content}, cast(#{citationsJson} as jsonb), #{status}
    , #{seq}, #{createdAt})

mapper.select:
select id, conversation_id, run_id, role, content, citations, status, seq, created_at from (
    select id, conversation_id, run_id, role, content, citations, status, seq, created_at from ai_message where conversation_id = #{conversationId} order by seq desc limit #{limit}
) t order by seq asc

select id, conversation_id, run_id, role, content, citations, status, seq, created_at from (
    select id, conversation_id, run_id, role, content, citations, status, seq, created_at from ai_message
where conversation_id = #{conversationId} and seq <= (select seq from ai_message where id = #{messageId} and
    conversation_id = #{conversationId})
    order by seq desc limit #{limit}
) t order by seq asc
